Algorithm Notas
  Dimension notas[4] As Integer;
  notas[0] <- 7;
  notas[1] <- 9;
  notas[2] <- 6;
  notas[3] <- 8;
  Define suma As Integer <- 0;
  For i <- 0 To 3 Do
    suma <- suma + notas[i];
  EndFor
  Write "Media: ", suma / 4;
EndAlgorithm

Algorithm Tabla
  Dimension tabla[2, 3] As Integer;
  For f <- 0 To 1 Do
    For c <- 0 To 2 Do
      tabla[f, c] <- (f + 1) * (c + 1);
    EndFor
  EndFor
  Write tabla[0, 2], " ", tabla[1, 2];
EndAlgorithm

Algorithm Fuera
  Dimension v[3] As Integer;
  v[3] <- 1;
EndAlgorithm

Algorithm Indices
  Dimension m[2, 2] As Integer;
  m[0] <- 1;
EndAlgorithm

Algorithm EscribirArreglo
  Dimension v[2] As Integer;
  v[0] <- 1;
  v[1] <- 2;
  Write v;
EndAlgorithm
